// ===== 1. 租户上下文（ThreadLocal） =====
public class TenantContext {
    // 推荐使用阿里 TTL 替代原生 ThreadLocal，支持线程池场景
    private static final ThreadLocal<String> TENANT_ID = new ThreadLocal<>();

    public static void setTenantId(String tenantId) {
        TENANT_ID.set(tenantId);
    }

    public static String getTenantId() {
        return TENANT_ID.get();
    }

    public static void clear() {
        TENANT_ID.remove(); // 必须在请求结束时清理，防止线程池复用时上下文泄漏
    }
}

// ===== 2. Spring 拦截器：从请求提取租户 =====
@Component
public class TenantWebInterceptor implements HandlerInterceptor {
    @Override
    public boolean preHandle(HttpServletRequest request,
            HttpServletResponse response, Object handler) {
        // 方案1: 从 Header 获取（内部系统）
        String tenantId = request.getHeader("X-Tenant-Id");

        // 方案2: 从子域名获取（SaaS 产品）
        // String host = request.getServerName(); // tenant1.saas.com
        // String tenantId = host.split("\\.")[0];

        // 方案3: 从 JWT Token 获取（移动端）
        // String token = request.getHeader("Authorization");
        // String tenantId = JwtUtil.parseTenantId(token);

        if (tenantId == null || tenantId.isEmpty()) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            throw new UnauthorizedException("缺少租户标识");
        }
        TenantContext.setTenantId(tenantId);
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request,
            HttpServletResponse response, Object handler, Exception ex) {
        TenantContext.clear(); // 请求结束必须清理
    }
}

// ===== 3. MyBatis 拦截器：自动注入 tenant_id =====
@Intercepts({
    @Signature(type = Executor.class, method = "query",
        args = {MappedStatement.class, Object.class, RowBounds.class, ResultHandler.class}),
    @Signature(type = Executor.class, method = "update",
        args = {MappedStatement.class, Object.class})
})
public class TenantSqlInterceptor implements Interceptor {
    // 需要租户隔离的表列表（从配置读取）
    private Set<String> tenantTables;

    @Override
    public Object intercept(Invocation invocation) throws Throwable {
        String tenantId = TenantContext.getTenantId();
        if (tenantId == null) {
            throw new IllegalStateException("租户上下文为空，拒绝执行SQL，防止跨租户泄露");
        }

        MappedStatement ms = (MappedStatement) invocation.getArgs()[0];
        Object parameter = invocation.getArgs()[1];
        BoundSql boundSql = ms.getBoundSql(parameter);
        String originalSql = boundSql.getSql();

        // 解析 SQL AST，对 tenantTables 中的表追加 WHERE tenant_id = ?
        String modifiedSql = SqlParser.addTenantCondition(originalSql, tenantId, tenantTables);

        // 重新构建 BoundSql 和 MappedStatement
        BoundSql newBoundSql = new BoundSql(ms.getConfiguration(), modifiedSql,
                boundSql.getParameterMappings(), parameter);
        MappedStatement newMs = copyFromMappedStatement(ms, newBoundSql);
        invocation.getArgs()[0] = newMs;

        return invocation.proceed();
    }
}

// ===== 4. 动态数据源路由（独立库模式） =====
public class TenantRoutingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        return TenantContext.getTenantId(); // 根据租户选择数据源
    }
}

// ===== 5. 异步场景的租户上下文传递 =====
public class TenantAwareRunnable implements Runnable {
    private final String tenantId;
    private final Runnable delegate;

    public TenantAwareRunnable(Runnable delegate) {
        this.tenantId = TenantContext.getTenantId(); // 提交时捕获
        this.delegate = delegate;
    }

    @Override
    public void run() {
        TenantContext.setTenantId(tenantId); // 执行前设置
        try {
            delegate.run();
        } finally {
            TenantContext.clear(); // 执行后清理
        }
    }
}
